/**
 * ApiKeysTable — API-key list table. Phase E, Round C.
 *
 * Mirrors TenantsTable's thead/tbody/row chrome (border-cog-divider rows,
 * text-start headers). A pure projection of the keys the route loaded — it
 * owns no fetch state; Rotate / Revoke bubble up to the route, which owns the
 * confirm-modal + mutation flow.
 *
 * Columns (start → end):
 *   Name        (key.name)
 *   Key         (masked <prefix>••••<last4>)
 *   Access      (read-only / read-write pill)
 *   Status      (active / expires-soon / expired / revoked pill)
 *   Created by  (creator's email)
 *   Last used   (relative-ish timestamp, or localized "Never used")
 *   Actions     (Rotate / Revoke)
 */

import type { ReactElement } from "react";
import type { ApiKey } from "../api/apiKeys";
import { MaskedKeyCell } from "./MaskedKeyCell";
import { AccessLevelPill } from "./AccessLevelPill";
import { ApiKeyStatusPill } from "./ApiKeyStatusPill";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { useLocale } from "@omnicore-platform/platform-chrome";

export interface ApiKeysTableProps {
  keys: ApiKey[];
  onRotate: (key: ApiKey) => void;
  onRevoke: (key: ApiKey) => void;
}

const HEADER_CLASS =
  "px-cog-4 py-cog-2 text-start text-eyebrow uppercase tracking-cog-eyebrow font-bold text-cog-text-tertiary";

export function ApiKeysTable({
  keys,
  onRotate,
  onRevoke,
}: ApiKeysTableProps): ReactElement {
  useLocale();
  return (
    <div
      data-testid="apikeys-table"
      className="overflow-hidden rounded-lg border border-cog-divider bg-cog-surface"
    >
      <table className="w-full border-collapse text-body-sm">
        <thead>
          <tr className="border-b border-cog-divider">
            <th scope="col" className={HEADER_CLASS}>
              {m.admin_apikey_col_name()}
            </th>
            <th scope="col" className={HEADER_CLASS}>
              {m.admin_apikey_col_key()}
            </th>
            <th scope="col" className={HEADER_CLASS}>
              {m.admin_apikey_col_access()}
            </th>
            <th scope="col" className={HEADER_CLASS}>
              {m.admin_apikey_col_status()}
            </th>
            <th scope="col" className={HEADER_CLASS}>
              {m.admin_apikey_col_created_by()}
            </th>
            <th scope="col" className={HEADER_CLASS}>
              {m.admin_apikey_col_last_used()}
            </th>
            <th scope="col" className={HEADER_CLASS}>
              {m.admin_apikey_col_actions()}
            </th>
          </tr>
        </thead>
        <tbody>
          {keys.map((key) => (
            <tr
              key={key.id}
              data-testid={`apikey-row-${key.id}`}
              className="border-b border-cog-divider last:border-0"
            >
              <td className="px-cog-4 py-cog-3 font-semibold text-cog-text-primary">
                {key.name}
              </td>
              <td className="px-cog-4 py-cog-3">
                <MaskedKeyCell
                  name={key.name}
                  tokenPrefix={key.token_prefix}
                  lastFour={key.last_four}
                />
              </td>
              <td className="px-cog-4 py-cog-3">
                <AccessLevelPill level={key.access_level} />
              </td>
              <td className="px-cog-4 py-cog-3">
                <ApiKeyStatusPill
                  status={key.status}
                  expiresAt={key.expires_at}
                />
              </td>
              <td className="px-cog-4 py-cog-3 text-cog-text-secondary">
                {key.created_by_email}
              </td>
              <td className="px-cog-4 py-cog-3 tabular-nums text-cog-text-secondary">
                {key.last_used_at ?? m.admin_apikey_last_used_never()}
              </td>
              <td className="px-cog-4 py-cog-3">
                <div className="flex items-center justify-end gap-cog-2">
                  <button
                    type="button"
                    data-testid="apikey-rotate"
                    onClick={() => onRotate(key)}
                    className="
                      inline-flex h-cog-6 items-center rounded-base border border-cog-divider
                      bg-cog-surface px-cog-3 text-body-sm font-semibold text-cog-text-primary
                      transition-colors duration-standard
                      hover:border-cog-border hover:bg-cog-surface-muted
                      focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-1
                    "
                  >
                    {m.admin_apikey_action_rotate()}
                  </button>
                  <button
                    type="button"
                    data-testid="apikey-revoke"
                    onClick={() => onRevoke(key)}
                    className="
                      inline-flex h-cog-6 items-center rounded-base border border-cog-danger-dark
                      bg-cog-surface px-cog-3 text-body-sm font-semibold text-cog-danger-600
                      transition-colors duration-standard
                      hover:border-cog-danger-600 hover:bg-cog-danger-50
                      focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-1
                      dark:border-cog-danger-800 dark:text-cog-danger-dark dark:hover:bg-cog-danger-950
                    "
                  >
                    {m.admin_apikey_action_revoke()}
                  </button>
                </div>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}


--- frontends/admin-mfe/src/apikeys/CreateApiKeyModal.tsx (325 lines) ---
/**
 * CreateApiKeyModal — issue a new API key (Phase E, Round B).
 *
 * Mirrors CreateTenantModal's chrome (shared Modal + Field + chip
 * radiogroups + useFieldErrors/zod). On success it hands the one-time
 * plaintext secret up via onIssued so the parent can open the
 * SecretRevealModal — the secret is never held here beyond the call.
 *
 * Fields:
 *   - Name (required)
 *   - Access level: Read-only (default) / Read-write
 *   - Expiry: 30 / 60 / 90 (default) / 365 days / Never
 */

import {
  useEffect,
  useState,
  type FormEvent,
  type ReactElement,
} from "react";
import { z } from "zod";
import {
  displayNameSchema,
  useFieldErrors,
  useLocale,
  type TranslatedString,
} from "@omnicore-platform/platform-chrome";
import { Modal } from "../components/Modal";
import {
  issueApiKey,
  type ApiKeyAccessLevel,
  type IssueApiKeyParams,
} from "../api/apiKeys";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";

const nameSchema = z.object({ name: displayNameSchema });

/** Expiry presets. days === null means no expiry (omit expires_at). */
interface ExpiryOption {
  readonly label: TranslatedString;
  readonly days: number | null;
}

const DAY_MS = 86_400_000;

function buildAccessOptions(): readonly {
  label: TranslatedString;
  value: ApiKeyAccessLevel;
}[] {
  return [
    { label: m.admin_apikey_access_read_only(), value: "read_only" },
    { label: m.admin_apikey_access_read_write(), value: "read_write" },
  ];
}

function buildExpiryOptions(): readonly ExpiryOption[] {
  return [
    { label: m.admin_apikey_expiry_30(), days: 30 },
    { label: m.admin_apikey_expiry_60(), days: 60 },
    { label: m.admin_apikey_expiry_90(), days: 90 },
    { label: m.admin_apikey_expiry_365(), days: 365 },
    { label: m.admin_apikey_expiry_never(), days: null },
  ];
}

export interface CreateApiKeyModalProps {
  open: boolean;
  onIssued: (secret: string) => void;
  onClose: () => void;
}

type SubmitState =
  | { phase: "idle" }
  | { phase: "submitting" }
  | { phase: "error" };

export function CreateApiKeyModal({
  open,
  onIssued,
  onClose,
}: CreateApiKeyModalProps): ReactElement {
  const [name, setName] = useState("");
  const [accessLevel, setAccessLevel] = useState<ApiKeyAccessLevel>("read_only");
  const [expiryDays, setExpiryDays] = useState<number | null>(90);
  const [submit, setSubmit] = useState<SubmitState>({ phase: "idle" });
  const { errors, setErrors, clear } = useFieldErrors();

  // Reset on re-open so a prior issue/error doesn't leak into the next.
  useEffect(() => {
    if (!open) return;
    setName("");
    setAccessLevel("read_only");
    setExpiryDays(90);
    setSubmit({ phase: "idle" });
    clear();
  }, [open, clear]);

  const accessOptions = buildAccessOptions();
  const expiryOptions = buildExpiryOptions();

  function computeExpiresAt(): string | undefined {
    if (expiryDays === null) return undefined;
    return new Date(Date.now() + expiryDays * DAY_MS).toISOString();
  }

  async function handleSubmit(e: FormEvent<HTMLFormElement>): Promise<void> {
    e.preventDefault();
    if (submit.phase === "submitting") return;

    const parsed = nameSchema.safeParse({ name });
    if (!parsed.success) {
      // Surface a localized name-required message rather than the shared
      // schema's English zod literal.
      setErrors((prev) => ({
        ...prev,
        name: m.admin_apikey_form_name_required(),
      }));
      return;
    }
    clear("name");

    const params: IssueApiKeyParams = {
      name: name.trim(),
      access_level: accessLevel,
    };
    const expiresAt = computeExpiresAt();
    if (expiresAt !== undefined) params.expires_at = expiresAt;

    setSubmit({ phase: "submitting" });
    try {
      const result = await issueApiKey(params);
      onIssued(result.secret);
    } catch {
      // issueApiKey throws an Error carrying the HTTP status + server detail;
      // we don't log it here (no logging in the api layer either) to avoid
      // leaking the response into the console — surface a user-facing inline
      // alert instead of crashing the modal.
      setSubmit({ phase: "error" });
    }
  }

  const submitting = submit.phase === "submitting";

  const footer = (
    <>
      <button
        type="button"
        onClick={onClose}
        className="
          inline-flex h-cog-6-5 items-center rounded-base border border-cog-divider
          bg-cog-surface px-cog-3 text-body-sm font-semibold text-cog-text-primary
          transition-colors duration-standard
          hover:border-cog-border hover:bg-cog-surface-muted
          focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-1
        "
      >
        {m.admin_apikey_create_cancel()}
      </button>
      <button
        type="submit"
        form="create-apikey-form"
        disabled={submitting}
        data-testid="apikey-create-submit"
        className="
          inline-flex h-cog-6-5 items-center rounded-base
          border border-cog-blue-600 bg-cog-blue-600 px-cog-3
          text-body-sm font-semibold text-white
          transition-colors duration-standard
          hover:border-cog-blue-700 hover:bg-cog-blue-700
          focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-1
          disabled:cursor-not-allowed disabled:opacity-50
          dark:border-cog-blue-700 dark:bg-cog-blue-700 dark:text-white
        "
      >
        {submitting ? m.admin_apikey_creating() : m.admin_apikey_create_cta()}
      </button>
    </>
  );

  return (
    <Modal
      title={m.admin_apikey_create_title()}
      eyebrow={m.admin_apikey_create_eyebrow()}
      open={open}
      onClose={onClose}
      footer={footer}
    >
      <form
        id="create-apikey-form"
        onSubmit={handleSubmit}
        data-testid="create-apikey-form"
        className="flex flex-col gap-cog-4"
      >
        <Field
          label={m.admin_apikey_form_name_label()}
          input={
            <input
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              aria-label={m.admin_apikey_form_name_label()}
              aria-required="true"
              aria-invalid={Boolean(errors.name)}
              data-testid="apikey-name"
              className="
                w-full rounded-base border border-cog-divider
                bg-cog-surface px-cog-2 py-cog-2
                text-body-sm text-cog-text-primary
                focus:border-cog-blue-600 focus:outline-none
              "
            />
          }
          error={errors.name}
        />

        <Field
          label={m.admin_apikey_form_access_label()}
          input={
            <div
              role="radiogroup"
              aria-label={m.admin_apikey_form_access_label()}
              data-testid="apikey-access"
              className="flex flex-wrap gap-cog-2"
            >
              {accessOptions.map((opt) => {
                const selected = accessLevel === opt.value;
                return (
                  <button
                    key={opt.value}
                    type="button"
                    role="radio"
                    aria-checked={selected}
                    onClick={() => setAccessLevel(opt.value)}
                    data-testid={`apikey-access-${opt.value}`}
                    className={chipClass(selected)}
                  >
                    {opt.label}
                  </button>
                );
              })}
            </div>
          }
        />

        <Field
          label={m.admin_apikey_form_expiry_label()}
          input={
            <div
              role="radiogroup"
              aria-label={m.admin_apikey_form_expiry_label()}
              data-testid="apikey-expiry"
              className="flex flex-wrap gap-cog-2"
            >
              {expiryOptions.map((opt) => {
                const selected = expiryDays === opt.days;
                const key = opt.days === null ? "never" : String(opt.days);
                return (
                  <button
                    key={key}
                    type="button"
                    role="radio"
                    aria-checked={selected}
                    onClick={() => setExpiryDays(opt.days)}
                    data-testid={`apikey-expiry-${key}`}
                    className={chipClass(selected)}
                  >
                    {opt.label}
                  </button>
                );
              })}
            </div>
          }
        />

        {submit.phase === "error" && (
          <p
            role="alert"
            data-testid="apikey-create-error"
            className="rounded-base border border-cog-danger-200 bg-cog-danger-50 px-cog-3 py-cog-2 text-body-sm text-cog-danger-600 dark:border-cog-danger-800 dark:bg-cog-danger-950 dark:text-cog-danger-dark"
          >
            {m.admin_apikey_create_failed()}
          </p>
        )}
      </form>
    </Modal>
  );
}

function chipClass(selected: boolean): string {
  return [
    "inline-flex h-cog-6 items-center rounded-base border px-cog-3 text-body-sm font-semibold",
    "transition-colors duration-standard",
    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-1",
    selected
      ? "border-cog-blue-600 bg-cog-blue-50 text-cog-blue-700 dark:bg-cog-blue-950 dark:text-cog-blue-300"
      : "border-cog-divider bg-cog-surface text-cog-text-primary hover:border-cog-border hover:bg-cog-surface-muted",
  ].join(" ");
}

function Field({
  label,
  input,
  error,
}: {
  label: TranslatedString;
  input: ReactElement;
  /** Zod-generated validation message — string, not TranslatedString. */
  error?: string;
}): ReactElement {
  useLocale();
  return (
    <div className="flex flex-col gap-cog-1">
      <p className="text-eyebrow uppercase tracking-cog-eyebrow font-bold text-cog-text-tertiary">
        {label}
      </p>
      {input}
      {error && (
        <span role="alert" className="text-body-sm text-cog-danger-500">
          {error}
        </span>
      )}
    </div>
  );
}


