/**
 * MaskedKeyCell — monospace masked-token cell for the API-key list. Phase E.
 *
 * Renders `<prefix>••••<last4>` (e.g. "omck_••••1a2b") in a mono face with an
 * accessible label naming the key, so a screen reader announces which key the
 * fragment belongs to. The full secret is never available here — only the
 * prefix + last four ever reach the MFE.
 */

import type { ReactElement } from "react";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { useLocale } from "@omnicore-platform/platform-chrome";

export interface MaskedKeyCellProps {
  name: string;
  tokenPrefix: string;
  lastFour: string;
}

export function MaskedKeyCell({
  name,
  tokenPrefix,
  lastFour,
}: MaskedKeyCellProps): ReactElement {
  useLocale();
  // Build the masked token outside the JSX text node so the `••••` literal
  // does not trip react/jsx-no-literals. The full secret never reaches here —
  // only the prefix + last four ever do.
  const masked = `${tokenPrefix}••••${lastFour}`;
  return (
    <span
      className="font-mono text-caption text-cog-text-tertiary text-start"
      aria-label={m.admin_apikey_masked_aria({ name, last4: lastFour })}
    >
      {masked}
    </span>
  );
}


--- frontends/admin-mfe/src/apikeys/RevokeApiKeyModal.tsx (84 lines) ---
/**
 * RevokeApiKeyModal — confirm revocation of an API key. Phase E, Round C.
 *
 * Revocation is irreversible (the secret can never be re-issued), so this is
 * a danger-styled confirm — but NOT a typed-confirmation flow: a single
 * "Revoke key" press is enough. Mirrors DeleteTenantModal's chrome on the
 * shared Modal. The route owns the mutation + reload; this surface only
 * collects the confirm.
 */

import type { ReactElement } from "react";
import { Modal } from "../components/Modal";
import type { ApiKey } from "../api/apiKeys";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { useLocale } from "@omnicore-platform/platform-chrome";

export interface RevokeApiKeyModalProps {
  open: boolean;
  apiKey: ApiKey | null;
  onConfirm: () => void;
  onClose: () => void;
}

export function RevokeApiKeyModal({
  open,
  apiKey,
  onConfirm,
  onClose,
}: RevokeApiKeyModalProps): ReactElement | null {
  useLocale();
  if (!apiKey) return null;

  const maskedKey = `${apiKey.token_prefix}••••${apiKey.last_four}`;

  const footer = (
    <>
      <button
        type="button"
        onClick={onClose}
        className="
          inline-flex h-cog-6-5 items-center rounded-base border border-cog-divider
