/**
 * useApiKeys — loads the org's API keys from admin-bff into a discriminated
 * loading/ready/error state. `reload()` re-fetches (used after issue / rotate
 * / revoke mutate the list). Phase E.
 */

import { useCallback, useEffect, useRef, useState } from "react";
import { listApiKeys, type ApiKey } from "../api/apiKeys";

type State =
  | { state: "loading" }
  | { state: "ready"; keys: ApiKey[] }
  | { state: "error"; message: string };

export function useApiKeys(): State & { reload: () => void } {
  const [s, setS] = useState<State>({ state: "loading" });
  // Guards setS against an in-flight listApiKeys() resolving after unmount,
  // which would otherwise log a "state update on an unmounted component"
  // warning and leak. Kept in a ref so `reload` stays referentially stable.
  const mountedRef = useRef(true);
  const reload = useCallback(() => {
    setS({ state: "loading" });
    listApiKeys()
      .then((keys) => {
        if (mountedRef.current) setS({ state: "ready", keys });
      })
      .catch((e: unknown) => {
        if (mountedRef.current) {
          setS({
            state: "error",
            message: e instanceof Error ? e.message : "error",
          });
        }
      });
  }, []);
  useEffect(() => {
    mountedRef.current = true;
    reload();
    return () => {
      mountedRef.current = false;
    };
  }, [reload]);
  return { ...s, reload };
}



