/**
 * ApiKeyStatusPill — colored pill for the API-key status column. Phase E.
 *
 * Active (live)   → blue dot (info-500)
 * Expires soon    → amber dot + "Expires in N days" (warning-500), shown when
 *                   an active key's expiry is > 0 and <= 14 days out
 * Expired         → neutral dot (text-secondary)
 * Revoked         → red dot (danger-500)
 *
 * Never color-alone: every state renders an icon-equivalent dot AND a text
 * label. The dot is aria-hidden; the label carries the meaning.
 */

import type { ReactElement } from "react";
import type { ApiKeyStatus } from "../api/apiKeys";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { useLocale } from "@omnicore-platform/platform-chrome";

const EXPIRES_SOON_DAYS = 14;
const MS_PER_DAY = 86_400_000;

interface Tone {
  dot: string;
  fg: string;
}

const LIVE_TONE: Tone = {
  dot: "bg-cog-info-500",
  fg: "text-cog-info-500 dark:text-cog-info-dark-text",
};
const WARNING_TONE: Tone = {
  dot: "bg-cog-warning-500",
  fg: "text-cog-warning-700 dark:text-cog-warning-dark-text",
};
const EXPIRED_TONE: Tone = {
  dot: "bg-cog-text-tertiary",
  fg: "text-cog-text-secondary",
};
const REVOKED_TONE: Tone = {
  dot: "bg-cog-danger-500",
  fg: "text-cog-danger-600 dark:text-cog-danger-dark",
};

export interface ApiKeyStatusPillProps {
  status: ApiKeyStatus;
  /** RFC-3339 expiry, or null when the key never expires. Drives the
   *  expires-soon warning when status is "active". */
  expiresAt: string | null;
}

/** Whole days until expiry (round-up), or null when there is no expiry. */
function daysUntil(expiresAt: string | null): number | null {
  if (expiresAt === null) return null;
  const expiry = new Date(expiresAt).getTime();
  if (Number.isNaN(expiry)) return null;
  return Math.ceil((expiry - Date.now()) / MS_PER_DAY);
}

export function ApiKeyStatusPill({
  status,
  expiresAt,
}: ApiKeyStatusPillProps): ReactElement {
  useLocale();

  let tone: Tone;
  let label: string;

  const days = daysUntil(expiresAt);
  const expiresSoon =
    status === "active" &&
    days !== null &&
    days > 0 &&
    days <= EXPIRES_SOON_DAYS;

  if (expiresSoon) {
    tone = WARNING_TONE;
    label = m.admin_apikey_status_expires_soon({ days: days as number });
  } else if (status === "active") {
    tone = LIVE_TONE;
    label = m.admin_apikey_status_live();
  } else if (status === "expired") {
    tone = EXPIRED_TONE;
    label = m.admin_apikey_status_expired();
  } else {
    tone = REVOKED_TONE;
    label = m.admin_apikey_status_revoked();
  }

  return (
    <span
      data-status={status}
      className={[
        "inline-flex items-center gap-cog-1-5 text-start text-micro font-semibold",
        tone.fg,
      ].join(" ")}
    >
      <span
        aria-hidden="true"
        className={["inline-block h-cog-1-5 w-cog-1-5 rounded-pill", tone.dot].join(
          " ",
        )}
      />
      {label}
    </span>
  );
}


