/**
 * SecretRevealModal — show-once plaintext secret reveal (Phase E, Round B).
 *
 * The plaintext API-key secret is returned exactly once by issue / rotate
 * and is never persisted in the MFE. This alertdialog forces the operator
 * to either copy it or explicitly acknowledge they've stored it before the
 * surface can be dismissed — closing it loses the secret forever.
 *
 * Designer direction Reveal-B:
 *  - role="alertdialog" (demands acknowledgement, not a passive dialog)
 *  - persistent warning, monospace inset secret block
 *  - Copy → clipboard + "Copied" + sr-only aria-live announcement
 *  - Ack checkbox as the clipboard-blocked fallback path
 *  - Done gated until (copied OR acked); Esc/backdrop are inert until then
 */

import { useState, type ReactElement } from "react";
import { Modal } from "../components/Modal";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { unsafeAsTranslated } from "@omnicore-platform/platform-chrome";

export interface SecretRevealModalProps {
  open: boolean;
  /** Title text — the caller passes an already-translated m.* string. */
  title: string;
  /** One-time plaintext secret. Never logged, never persisted. */
  secret: string;
  onClose: () => void;
}

export function SecretRevealModal({
  open,
  title,
  secret,
  onClose,
}: SecretRevealModalProps): ReactElement {
  const [copied, setCopied] = useState(false);
  const [copyError, setCopyError] = useState(false);
  const [acked, setAcked] = useState(false);
  const warningId = "apikey-secret-warning";
  const canDismiss = copied || acked;

  async function handleCopy(): Promise<void> {
    // Clear any prior failure so a retry presents a clean slate.
    setCopyError(false);
    try {
      await navigator.clipboard.writeText(secret);
      setCopied(true);
    } catch {
      // Clipboard can be blocked (permissions, insecure context). Surface a
      // localized error and keep Done locked — the ack checkbox is the
      // fallback path. Swallowing the rejection here keeps the onClick
      // promise from floating as an unhandled rejection.
      setCopyError(true);
    }
  }

  const footer = (
    <button
      type="button"
      onClick={onClose}
      disabled={!canDismiss}
      data-testid="apikey-secret-done"
      className="
        inline-flex h-cog-6-5 items-center rounded-base
        border border-cog-blue-600 bg-cog-blue-600 px-cog-3
        text-body-sm font-semibold text-white
        transition-colors duration-standard
        hover:border-cog-blue-700 hover:bg-cog-blue-700
        focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-1
        disabled:cursor-not-allowed disabled:opacity-50
        dark:border-cog-blue-700 dark:bg-cog-blue-700 dark:text-white
      "
    >
      {m.admin_apikey_secret_done()}
    </button>
  );

  return (
    <Modal
      // i18n-allow: title is an already-translated m.* string supplied by the caller
      title={unsafeAsTranslated(title)}
      open={open}
      onClose={onClose}
      role="alertdialog"
      dismissible={canDismiss}
      describedById={warningId}
      footer={footer}
    >
      <div className="flex flex-col gap-cog-4">
        <p
          id={warningId}
          role="alert"
          className="
            rounded-base border border-cog-warning-200 bg-cog-warning-50
            px-cog-3 py-cog-2 text-body-sm text-cog-warning-700
            dark:border-cog-warning-800 dark:bg-cog-warning-950 dark:text-cog-warning-300
          "
        >
          {m.admin_apikey_secret_warning()}
        </p>

        <div className="flex items-stretch gap-cog-2">
          <code
            data-testid="apikey-secret-value"
            className="
              flex-1 select-all break-all rounded-base
              border border-cog-divider bg-cog-surface-muted
              px-cog-3 py-cog-2 font-mono text-body-sm text-cog-text-primary
              shadow-cog-e1
            "
          >
            {secret}
          </code>
          <button
            type="button"
            onClick={() => {
              void handleCopy();
            }}
            data-testid="apikey-secret-copy"
            className="
              inline-flex h-auto shrink-0 items-center rounded-base
              border border-cog-divider bg-cog-surface px-cog-3
              text-body-sm font-semibold text-cog-text-primary
              transition-colors duration-standard
              hover:border-cog-border hover:bg-cog-surface-muted
              focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-1
            "
          >
            {copied ? m.admin_apikey_secret_copied() : m.admin_apikey_secret_copy()}
          </button>
        </div>

        {copyError && (
          <p
            role="alert"
            data-testid="apikey-secret-copy-error"
            className="
              rounded-base border border-cog-danger-200 bg-cog-danger-50
              px-cog-3 py-cog-2 text-body-sm text-cog-danger-600
              dark:border-cog-danger-800 dark:bg-cog-danger-950 dark:text-cog-danger-dark
            "
          >
            {m.admin_apikey_secret_copy_failed()}
          </p>
        )}

        <label className="flex items-center gap-cog-2 text-body-sm text-cog-text-primary">
          <input
            type="checkbox"
            checked={acked}
            onChange={(e) => setAcked(e.target.checked)}
            className="
              h-cog-4 w-cog-4 rounded-sm border-cog-border text-cog-blue-600
              focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-1
            "
          />
          {m.admin_apikey_secret_stored_ack()}
        </label>

        <span aria-live="polite" className="sr-only">
          {copied ? m.admin_apikey_secret_copied_announce() : ""}
        </span>
      </div>
    </Modal>
  );
}


